// AccountNeedsStore says "Fill in {store} in Settings › Account & Upload first"
// in the language the app shows under cx.
//
// Why the player cannot upload: the chosen storage is not filled in. Names the settings page.
func AccountNeedsStore(cx *core.Scope, store string) string { return For(cx).AccountNeedsStore(store) }

// AccountNeedsStore is the package's AccountNeedsStore in the language of msgs.
func (msgs Messages) AccountNeedsStore(store string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.AccountNeedsStore(store))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].AccountNeedsStore; f != nil {
			return f(store)
		}
		switch lang {
		case "", "en":
			return "Fill in " + msgs.arg(store) + " in Settings › Account & Upload first"
		case "ja":
			return "先に「設定 › アカウントとアップロード」で " + store + " の情報を入力してください"
		case "ko":
			return "먼저 ‘설정 › 계정 및 업로드’에서 " + store + " 정보를 입력하십시오"
		case "zh-Hans":
			return "先在「设置 › 账号与上传」里填写 " + store
		case "zh-Hant":
			return "先在「設定 › 帳號與上傳」中填寫 " + store
		}
	}
}

