// FilmLineOf says "Line {line} of {total}"
// in the language the app shows under cx.
//
// Message on the picture after moving to a subtitle line: its number, counting from 1, and how many lines the film has.
func FilmLineOf(cx *core.Scope, line int, total int) string { return For(cx).FilmLineOf(line, total) }

// FilmLineOf is the package's FilmLineOf in the language of msgs.
func (msgs Messages) FilmLineOf(line int, total int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.FilmLineOf(line, total))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].FilmLineOf; f != nil {
			return f(line, total)
		}
		switch lang {
		case "", "en":
			return "Line " + msgs.arg(i18n.FormatNumber("en", float64(line))) + " of " + msgs.arg(i18n.FormatNumber("en", float64(total)))
		case "ja":
			return "セリフ " + i18n.FormatNumber("ja", float64(line)) + " / " + i18n.FormatNumber("ja", float64(total))
		case "ko":
			return "대사 " + i18n.FormatNumber("ko", float64(line)) + " / " + i18n.FormatNumber("ko", float64(total))
		case "zh-Hans":
			return "第 " + i18n.FormatNumber("zh-Hans", float64(line)) + " / " + i18n.FormatNumber("zh-Hans", float64(total)) + " 句"
		case "zh-Hant":
			return "第 " + i18n.FormatNumber("zh-Hant", float64(line)) + " / " + i18n.FormatNumber("zh-Hant", float64(total)) + " 句"
		}
	}
}

