// QueueYtdlpUpdated says "Updated the download component to {version} and restarted {count, plural, one {# download} other {# downloads}}."
// in the language the app shows under cx.
//
// Message bar after yt-dlp was updated and the downloads it was too old for were queued again.
func QueueYtdlpUpdated(cx *core.Scope, version string, count int) string {
	return For(cx).QueueYtdlpUpdated(version, count)
}

// QueueYtdlpUpdated is the package's QueueYtdlpUpdated in the language of msgs.
func (msgs Messages) QueueYtdlpUpdated(version string, count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.QueueYtdlpUpdated(version, count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].QueueYtdlpUpdated; f != nil {
			return f(version, count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			b.WriteString("Updated the download component to ")
			b.WriteString(msgs.arg(version))
			b.WriteString(" and restarted ")
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" download")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" downloads")
			}
			b.WriteString(".")
			return b.String()
		case "ja":
			return "ダウンロードコンポーネントを " + version + " にアップデートし、" + i18n.FormatNumber("ja", float64(count)) + " 本の動画のダウンロードを再開しました。"
		case "ko":
			return "다운로드 구성 요소를 " + version + "(으)로 업데이트하고 동영상 " + i18n.FormatNumber("ko", float64(count)) + "개의 다운로드를 다시 시작했습니다."
		case "zh-Hans":
			return "下载组件已更新到 " + version + "，已重新开始下载 " + i18n.FormatNumber("zh-Hans", float64(count)) + " 个视频。"
		case "zh-Hant":
			return "下載元件已更新到 " + version + "，已重新開始下載 " + i18n.FormatNumber("zh-Hant", float64(count)) + " 部影片。"
		}
	}
}

