// SettingsGeneralShowInFinder says "{platform, select, macOS {Show in Finder} Windows {Show in File Explorer} other {Show in File Manager}}"
// in the language the app shows under cx.
//
// Button showing the library folder in the system's file manager. {platform} is the system the app runs on: macOS, Windows or another (Linux); each case names that system's file manager.
func SettingsGeneralShowInFinder(cx *core.Scope, platform string) string {
	return For(cx).SettingsGeneralShowInFinder(platform)
}

// SettingsGeneralShowInFinder is the package's SettingsGeneralShowInFinder in the language of msgs.
func (msgs Messages) SettingsGeneralShowInFinder(platform string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.SettingsGeneralShowInFinder(platform))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].SettingsGeneralShowInFinder; f != nil {
			return f(platform)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("Show in Finder")
			case "Windows":
				b.WriteString("Show in File Explorer")
			default:
				b.WriteString("Show in File Manager")
			}
			return b.String()
		case "ja":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("Finder で表示")
			case "Windows":
				b.WriteString("エクスプローラーで表示")
			default:
				b.WriteString("ファイルマネージャーで表示")
			}
			return b.String()
		case "ko":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("Finder에서 보기")
			case "Windows":
				b.WriteString("파일 탐색기에서 보기")
			default:
				b.WriteString("파일 관리자에서 보기")
			}
			return b.String()
		case "zh-Hans":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("在访达中显示")
			case "Windows":
				b.WriteString("在文件资源管理器中显示")
			default:
				b.WriteString("在文件管理器中显示")
			}
			return b.String()
		case "zh-Hant":
			var b strings.Builder
			switch platform {
			case "macOS":
				b.WriteString("在 Finder 中顯示")
			case "Windows":
				b.WriteString("在檔案總管中顯示")
			default:
				b.WriteString("在檔案管理員中顯示")
			}
			return b.String()
		}
	}
}

